# ---------------------------------------------------------------- utilidades de texto
def ahora_utc():
    return dt.datetime.now(dt.timezone.utc)


def fi(x):
    return f"{x}".replace(".", ",")


def num_txt(x):
    return f"{x:.0f}" if abs(x - round(x)) < 1e-9 else fi(round(x, 1))


def pct(p, dec=0):
    return "—" if p is None else (f"{100 * p:.{dec}f} %").replace(".", ",")


def dinero(x):
    if x is None:
        return "—"
    x = float(x)
    t = f"{abs(x):,.0f}" if abs(x - round(x)) < 0.005 else f"{abs(x):,.2f}"
    return ("−$" if x < 0 else "$") + t.replace(",", "X").replace(".", ",").replace("X", ".")


def costo_txt(costo):
    if costo is None:
        return "costo esperado —"
    return f"costo esperado {dinero(costo)}" if costo >= 0 else f"ganancia esperada {dinero(-costo)}"


def uno_de_cada(p):
    if not p or p <= 0 or p > 0.5:
        return ""
    return "1 de cada " + f"{1 / p:,.0f}".replace(",", ".")


def ncdf(x):
    return 0.5 * (1 + math.erf(x / math.sqrt(2)))


def americana_txt(a):
    if a is None:
        return ""
    a = int(round(float(a)))
    return f"+{a}" if a > 0 else f"{a}"


def linea_txt(x):
    return "" if x is None else (f"{x:+.1f}" if abs(x - round(x)) > 1e-9 else f"{x:+.0f}")


def hora_ccs(iso):
    if not iso:
        return ""
    try:
        t = dt.datetime.fromisoformat(str(iso).replace("Z", "+00:00")).astimezone(CCS)
    except ValueError:
        return str(iso)
    h = t.strftime("%I:%M %p").lstrip("0").lower().replace("am", "a. m.").replace("pm", "p. m.")
    return f"{S.DIAS[t.weekday()]} {h}"


def normal(s):
    s = unicodedata.normalize("NFKD", s or "").encode("ascii", "ignore").decode().lower()
    return re.sub(r"[^a-z0-9+\-\. ]", " ", s)


def _guardar_json(ruta, obj):
    ruta.parent.mkdir(parents=True, exist_ok=True)
    tmp = ruta.with_suffix(ruta.suffix + ".tmp")
    tmp.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
    os.replace(tmp, ruta)


def _leer_json(ruta, defecto):
    try:
        return json.loads(ruta.read_text(encoding="utf-8"))
    except (FileNotFoundError, json.JSONDecodeError):
        return defecto


def _num(x):
    if x in (None, ""):
        return None
    try:
        return float(str(x).replace("$", "").replace(",", "").strip())
    except ValueError:
        return None


def _entero(x):
    if x in (None, ""):
        return None
    try:
        v = int(round(float(str(x).replace("+", "").replace(",", "").replace("−", "-").strip())))
        return v if v != 0 else None
    except ValueError:
        return None


def _linea(x):
    if x in (None, ""):
        return None
    t = str(x).replace("½", ".5").replace(",", ".").replace("−", "-").replace(" ", "")
    if t.lower() in ("pk", "pick", "pickem", "pick'em"):
        return 0.0
    try:
        return float(t)
    except ValueError:
        return None


# ---------------------------------------------------------------- v1.3.1: semanas NFL y candado del registro
def clave_semana(b):
    """(temporada, fase, semana) de ESPN: fase 1 pretemporada, 2 temporada regular, 3 playoffs (semana 1 = comodines)."""
    return (int(b.get("temporada") or S.TEMPORADA), int(b.get("fase") or 2), int(b.get("semana") or 0))


def nombre_semana(clave, corto=False):
    t, f, s = clave
    if f == 3:
        txt = PLAYOFFS_ESPN.get(s, (f"Playoffs {s}", None))[0]
    elif f == 1:
        txt = f"Pretemporada {s}"
    else:
        txt = f"Semana {s}" if s else "Sin semana"
    if corto and f == 2:
        txt = str(s)
    return txt if t == S.TEMPORADA else f"{txt} de {t}"


def semana_nflverse(fase, semana):
    """Semana de ESPN → semana de nflverse (en playoffs nflverse sigue con 19-22)."""
    return PLAYOFFS_ESPN.get(semana, (None, None))[1] if int(fase or 2) == 3 else semana


def leer_semana(txt, actual=None):
    """«4», «semana 4», «comodines»… → clave (temporada, fase, semana) o None."""
    t = _clave_nombre(txt).replace("semana", "").strip()
    if t.isdigit():
        return (S.TEMPORADA, 2, int(t))
    for s, (nom, _) in PLAYOFFS_ESPN.items():
        if t and _clave_nombre(nom).startswith(t):
            return (S.TEMPORADA, 3, s)
    return None


def fechas_txt(isos):
    """«8-12 oct» o «30 sep-4 oct» (Caracas) a partir de las horas de inicio."""
    ts = sorted(t for t in (S.t_utc(x) for x in isos if x) if t)
    if not ts:
        return ""
    a, b = ts[0].astimezone(CCS), ts[-1].astimezone(CCS)
    if a.date() == b.date():
        return f"{a.day} {S.MESES[a.month - 1]}"
    if a.month == b.month:
        return f"{a.day}-{b.day} {S.MESES[a.month - 1]}"
    return f"{a.day} {S.MESES[a.month - 1]}-{b.day} {S.MESES[b.month - 1]}"


@contextlib.contextmanager
def candado(ruta=CANDADO, espera_s=90.0):
    """Candado de archivo (flock). El bot y el modo auto escriben el registro solo adentro de él, por poco tiempo."""
    import fcntl
    ruta.parent.mkdir(parents=True, exist_ok=True)
    with open(ruta, "a+") as fh:
        t0 = time.time()
        while True:
            try:
                fcntl.flock(fh, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                if time.time() - t0 > espera_s:
                    raise TimeoutError("el registro de parlays está ocupado")
                time.sleep(0.2)
        try:
            yield
        finally:
            fcntl.flock(fh, fcntl.LOCK_UN)


def media_txt(x):
    """−2½, +4, 44½ (líneas de apuestas)."""
    if x is None:
        return ""
    x = float(x)
    s = "−" if x < 0 else ""
    a = abs(x)
    ent = int(math.floor(a + 1e-9))
    return s + (f"{ent}½" if abs(a - ent - 0.5) < 1e-9 else num_txt(a))


def linea_eq_txt(x):
    if x is None:
        return ""
    return "PK" if abs(float(x)) < 1e-9 else (("+" if x > 0 else "") + media_txt(x))


# ---------------------------------------------------------------- ESPN
class ESPN:
    """API pública de ESPN (sin llave). `traer` se reemplaza en las pruebas."""

    def __init__(self):
        self._c = {}

    def traer(self, url):
        """Dos intentos (ESPN a veces tarda); el segundo error se propaga."""
        import requests
        for intento in (1, 2):
            try:
                r = requests.get(url, timeout=(6, 20), headers={"User-Agent": "nfl-secret-lab/1 (uso personal)"})
                r.raise_for_status()
                return r.json()
            except Exception:  # noqa: BLE001
                if intento == 2:
                    raise
                time.sleep(2)

    def _get(self, url):
        if url not in self._c:
            self._c[url] = self.traer(url)
        return self._c[url]

    def tablero(self, semana=None, temporada=None, fase=2):
        url = ESPN_TABLERO + (f"?seasontype={int(fase or 2)}&week={semana}&dates={temporada}" if semana else "")
        return self._get(url)

    def resumen(self, evento):
        return self._get(ESPN_RESUMEN.format(evento))


def _abbr(a):
    return ESPN_A_NFLVERSE.get(a, a)


def _seg_reloj(txt):
    try:
        m, s = str(txt).split(":")
        return int(m) * 60 + int(float(s))
    except ValueError:
        return 0


def juegos_del_tablero(tab):
    out = []
    semana = (tab.get("week") or {}).get("number")
    temporada = (tab.get("season") or {}).get("year")
    fase = (tab.get("season") or {}).get("type") or 2
    for e in tab.get("events", []):
        c = e["competitions"][0]
        st = c.get("status", {})
        ty = st.get("type", {})
        eq = {}
        for t in c.get("competitors", []):
            tm = t.get("team", {})
            eq[t.get("homeAway")] = dict(abbr=_abbr(tm.get("abbreviation", "")), espn_id=str(tm.get("id")),
                                        nombre=tm.get("displayName", ""), apodo=tm.get("name") or tm.get("shortDisplayName", ""),
                                        puntos=int(float(t.get("score") or 0)))
        out.append(dict(id=str(e["id"]), inicio=e.get("date") or c.get("date"), estado=ty.get("state", "pre"),
                        detalle=ty.get("shortDetail") or ty.get("detail", ""), periodo=int(st.get("period") or 0),
                        reloj=st.get("displayClock", "0:00"), local=eq.get("home", {}), visita=eq.get("away", {}),
                        situacion=c.get("situation") or {}, semana=(e.get("week") or {}).get("number", semana),
                        temporada=(e.get("season") or {}).get("year", temporada),
                        fase=int((e.get("season") or {}).get("type") or fase),
                        cancelado=ty.get("name") in ("STATUS_CANCELED", "STATUS_POSTPONED")))
    return out


def jugadas_de_resumen(res, n=10):
    """Últimas n jugadas (la más nueva primero), con el estado al empezar cada una."""
    dr = res.get("drives") or {}
    series = list(dr.get("previous") or [])
    if dr.get("current") and (not series or series[-1].get("id") != dr["current"].get("id")):
        series.append(dr["current"])
    ids = {}
    for c in res.get("header", {}).get("competitions", [{}])[0].get("competitors", []):
        ids[str(c.get("id") or c.get("team", {}).get("id"))] = _abbr(c.get("team", {}).get("abbreviation", ""))
    pl_ = []
    for s in series:
        eq = _abbr((s.get("team") or {}).get("abbreviation", ""))
        for p in s.get("plays", []):
            st = p.get("start") or {}
            pl_.append(dict(texto=p.get("text", ""), periodo=(p.get("period") or {}).get("number", 0),
                            reloj=(p.get("clock") or {}).get("displayValue", ""), local=p.get("homeScore"), visita=p.get("awayScore"),
                            ataque=ids.get(str((st.get("team") or {}).get("id")), eq), down=st.get("down"), dist=st.get("distance"),
                            anota=bool(p.get("scoringPlay")), fin=p.get("end") or {}, ids=ids))
    return list(reversed(pl_))[:n]


def _yte_de_texto(txt, pos):
    """Yardas a la zona de anotación desde «1st & 10 at PIT 35» o «& Goal at CLE 2»."""
    if re.search(r"at\s+50\b", txt or ""):
        return 50
    m = re.search(r"at\s+([A-Z]{2,3})\s+(\d{1,2})", txt or "")
    if not m or not pos:
        return None
    eq = {"CLV": "CLE", "BLT": "BAL", "HST": "HOU", "ARZ": "ARI", "SL": "LA"}.get(m.group(1), _abbr(m.group(1)))
    return 100 - int(m.group(2)) if eq == pos else int(m.group(2))


def estado_vivo(juego, res=None):
    """Posesión, down, distancia, yardas a la meta y última jugada: del tablero; lo que falte, de la última jugada."""
    sit = juego.get("situacion") or {}
    ids = {juego["local"].get("espn_id"): juego["local"].get("abbr"), juego["visita"].get("espn_id"): juego["visita"].get("abbr")}
    pos = ids.get(str(sit.get("possession"))) if sit.get("possession") else None
    down, dist, yte = sit.get("down"), sit.get("distance"), sit.get("yardsToEndzone")
    ultima = (sit.get("lastPlay") or {}).get("text", "")
    y_txt = _yte_de_texto(sit.get("downDistanceText") or sit.get("possessionText") or "", pos)
    if y_txt is not None and (yte is None or not (1 <= int(yte) <= 99)):
        yte = y_txt
    if res is not None and (pos is None or yte is None):
        jj = jugadas_de_resumen(res, 1)
        if jj:
            fin, i = jj[0]["fin"], jj[0]["ids"]
            pos = pos or i.get(str((fin.get("team") or {}).get("id")))
            down = down if down is not None else fin.get("down")
            dist = dist if dist is not None else fin.get("distance")
            yte = yte if yte is not None else fin.get("yardsToEndzone")
            ultima = ultima or jj[0]["texto"]
    return dict(pos=pos, down=down, dist=dist, yte=yte, ultima=ultima)


def fraccion_restante(juego):
    per, seg = juego.get("periodo", 0), _seg_reloj(juego.get("reloj", "0:00"))
    if juego.get("estado") == "pre" or per == 0:
        return 1.0
    if per >= 5:
        return max(seg, 1) / 3600.0
    return max(0.0, ((4 - per) * 900 + seg) / 3600.0)


def _celda_dist(d):
    d = int(d)
    return "1" if d <= 1 else "2-3" if d <= 3 else "4-6" if d <= 6 else "7-10" if d <= 10 else "11+"


def tasas_serie(down, dist, yte, tramo):
    """(p_TD, p_FG, p_TD_rival) de la serie desde esta situación (nflverse 2016-2019); celdas con < 30 jugadas → más gruesa."""
    if down not in (1, 2, 3, 4) or yte is None or dist is None or not (1 <= int(yte) <= 99):
        return 0.0, 0.0, 0.0
    c, y = _celda_dist(dist), max(0, min(95, int(yte) // 5 * 5))
    for tr in ([tramo, "2min"] if tramo == "30s" else [tramo]) + ["todo"]:
        t = SERIE.get((int(down), c, y, tr))
        if t and t[3] >= 30:
            return t[0], t[1], t[2]
    t = SERIE.get((int(down), c, y, "todo"))
    return (t[0], t[1], t[2]) if t else (0.0, 0.0, 0.0)


def serie_vivo(ev, juego):
    """Resultados posibles de la serie en curso en puntos para el equipo con el balón: [(prob, puntos, puntos al total)]
    y un ajuste fijo (punto extra pendiente). Down 0: TD sin conversión → +0,95 y patea; si no, patea y el rival recibe."""
    per, seg = juego.get("periodo", 0), _seg_reloj(juego.get("reloj", "0:00"))
    tramo = ("30s" if seg <= 30 else "2min" if seg <= 120 else "normal") if (per in (2, 4) or per >= 5) else "normal"
    d = ev.get("down")
    if d in (1, 2, 3, 4):
        td, fg, otd = tasas_serie(d, ev.get("dist"), ev.get("yte"), tramo)
        return [(td, 7, 7), (fg, 3, 3), (otd, -7, 7), (max(0.0, 1 - td - fg - otd), 0, 0)], 0.0
    u = (ev.get("ultima") or "").upper()
    ajuste = PAT if ("TOUCHDOWN" in u and not any(x in u for x in ("KICK)", "EXTRA POINT", "TWO-POINT", "PAT ", "KICK IS"))) else 0.0
    td, fg, otd = tasas_serie(1, 10, 65, tramo)
    return [(td, -7, 7), (fg, -3, 3), (otd, 7, 7), (max(0.0, 1 - td - fg - otd), 0, 0)], ajuste


# ---------------------------------------------------------------- referencia (Pinnacle del bot o consenso de nflverse)
class Referencia:
    """Línea de un juego en la orientación de nflverse, con las funciones de semana.py (sin vig por potencia y la
    distribución del margen anclada). cierre=True: última foto de Pinnacle antes del inicio (o el consenso al cierre)."""

    def __init__(self, fila, ahora, cierre=False, bot_dir=BOT_DIR):
        self.gid, self.local, self.visita = fila["game_id"], fila["home_team"], fila["away_team"]
        self.total = _num(fila.get("total_line"))
        p = None
        if cierre and fila.get("inicio") is not None:
            c = S.cierre_pin(bot_dir, {self.gid: fila["inicio"]}).get(self.gid)
            if c:
                p = dict(c, horas=round(c.get("min_antes", 0) / 60, 2))
        if p is None and not cierre:
            p = S.lineas_bot(bot_dir, "pinnacle", [self.gid], ahora, PIN_MAX_H).get(self.gid)
        self.r = S.referencia_juego(fila, p)
        self.fuente = "sin línea" if self.r is None else ("Pinnacle" + (" al cierre" if cierre else f" de hace {self.r['horas']:.1f} h".replace(".", ","))
                                                          if self.r["fuente"] == "pinnacle" else "consenso nflverse")
        self._M = None

    def ok(self):
        return self.r is not None

    def es_local(self, eq):
        return eq == self.local

    def margen_esperado(self, eq):
        """Margen final esperado del equipo según la línea (−hándicap)."""
        h = -float(self.r["hcp_local"])
        return h if self.es_local(eq) else -h

    def p_ml(self, eq):
        p = S.sin_vig_potencia(self.r["ml_local"], self.r["ml_visit"])
        return p if self.es_local(eq) else 1 - p

    def p_spread(self, eq, h):
        if self._M is None:
            p_sp = (S.sin_vig_potencia(self.r["sp_local"], self.r["sp_visit"])
                    if self.r.get("sp_local") is not None and self.r.get("sp_visit") is not None else None)
            self._M = S.Margen(self.r["hcp_local"], p_sp)
        return self._M.lado(self.es_local(eq), float(h))

    def p_total(self, linea, over=True):
        if self.total is None:
            return None, None
        if abs(linea - round(linea)) < 1e-9:
            po = 1 - ncdf((linea + 0.5 - self.total) / SD_TOTAL_PREVIA)
            pp = ncdf((linea + 0.5 - self.total) / SD_TOTAL_PREVIA) - ncdf((linea - 0.5 - self.total) / SD_TOTAL_PREVIA)
        else:
            po, pp = 1 - ncdf((linea - self.total) / SD_TOTAL_PREVIA), 0.0
        return (po if over else 1 - po - pp), pp


# ---------------------------------------------------------------- probabilidad de una pata
def prob_previa(pata, ref):
    """Antes del juego: el método validado (sección 3) con la referencia; totales con la normal de 6b (sin Pinnacle)."""
    if not ref.ok():
        return None, None
    if pata["tipo"] == "ML":
        return ref.p_ml(pata["equipo"]), 0.0
    if pata["tipo"] == "SPREAD":
        return ref.p_spread(pata["equipo"], pata["linea"])
    return ref.p_total(float(pata["linea"]), pata.get("lado_total", "OVER") == "OVER")


def prob_vivo(pata, juego, ref, res=None):
    """En juego: la aproximación del registro 42. Terminado: 1/0 y push."""
    loc, vis = juego["local"].get("puntos", 0), juego["visita"].get("puntos", 0)
    if pata["tipo"] in ("ML", "SPREAD"):
        eq = pata["equipo"]
        es_loc_espn = eq == juego["local"].get("abbr")
        dif = (loc - vis) if es_loc_espn else (vis - loc)
        linea = 0.0 if pata["tipo"] == "ML" else float(pata["linea"])
        if juego["estado"] == "post":
            v = dif + linea
            return (1.0, 0.0) if v > 0 else (0.0, 1.0) if v == 0 else (0.0, 0.0)
        if not ref.ok():
            return None, None
        f = fraccion_restante(juego)
        mezcla, base = [(1.0, 0, 0)], dif + ref.margen_esperado(eq) * f
        ev = estado_vivo(juego, res)
        if ev.get("pos"):
            mz, aj = serie_vivo(ev, juego)
            signo = 1 if ev["pos"] == eq else -1
            mezcla = [(pr, signo * x, xt) for pr, x, xt in mz]
            base += signo * aj
        sd = math.sqrt(SIG_MARGEN ** 2 * f + PISO_MARGEN ** 2 * min(1.0, f / F0_MARGEN) + 0.01)

        def mas(z):
            return sum(pr * (1 - ncdf((z - (base + x)) / sd)) for pr, x, _ in mezcla)
        k = -linea
        if abs(k - round(k)) < 1e-9:
            pg, pp = mas(k + 0.5), mas(k - 0.5) - mas(k + 0.5)
        else:
            pg, pp = mas(k), 0.0
        return pg, (pp if pata["tipo"] == "SPREAD" else pp)
    tot = loc + vis
    linea = float(pata["linea"])
    over = pata.get("lado_total", "OVER") == "OVER"
    if juego["estado"] == "post":
        if tot == linea:
            return 0.0, 1.0
        return (1.0, 0.0) if (tot > linea) == over else (0.0, 0.0)
    if ref.total is None:
        return None, None
    f = fraccion_restante(juego)
    mezcla, base = [(1.0, 0, 0)], tot + ref.total * f
    ev = estado_vivo(juego, res)
    if ev.get("pos"):
        mezcla, aj = serie_vivo(ev, juego)
        base += aj
    sd = math.sqrt(SIG_TOTAL ** 2 * f + PISO_TOTAL ** 2 * min(1.0, f / F0_TOTAL) + 0.01)

    def mas_t(z):
        return sum(pr * (1 - ncdf((z - (base + xt)) / sd)) for pr, _, xt in mezcla)
    if abs(linea - round(linea)) < 1e-9:
        po, pp = mas_t(linea + 0.5), mas_t(linea - 0.5) - mas_t(linea + 0.5)
    else:
        po, pp = mas_t(linea), 0.0
    return (po if over else 1 - po - pp), pp


# ---------------------------------------------------------------- v1.4 (42n): props de jugador
# Estadística → (claves del boxscore de ESPN que se suman, singular, plural). Claves verificadas el 15-oct-2026 con los
# resúmenes reales de SF @ SEA y DEN @ LAC (semana 5). «Anota TD»: carrera, recepción, devoluciones y TD de defensa.
PROP_STATS = {
    "TD": (("rushingTouchdowns", "receivingTouchdowns", "kickReturnTouchdowns", "puntReturnTouchdowns", "defensiveTouchdowns"), "TD", "TD"),
    "PASS_TD": (("passingTouchdowns",), "pase de TD", "pases de TD"),
    "FG": (("fieldGoalsMade/fieldGoalAttempts",), "gol de campo", "goles de campo"),
    "PASS_YDS": (("passingYards",), "yarda de pase", "yardas de pase"),
    "RUSH_YDS": (("rushingYards",), "yarda por tierra", "yardas por tierra"),
    "REC_YDS": (("receivingYards",), "yarda de recepción", "yardas de recepción"),
    "RECEPTIONS": (("receptions",), "recepción", "recepciones"),
}
YARDAS = ("PASS_YDS", "RUSH_YDS", "REC_YDS")
ALIAS_STAT = {"TOUCHDOWN": "TD", "TOUCHDOWNS": "TD", "ANYTIME_TD": "TD", "SCORE": "TD", "PASSING_TD": "PASS_TD", "PASSING_TDS": "PASS_TD",
              "PASS_TDS": "PASS_TD", "FIELD_GOALS": "FG", "FIELD_GOAL": "FG", "FGS": "FG", "PASSING_YARDS": "PASS_YDS",
              "RUSHING_YARDS": "RUSH_YDS", "RECEIVING_YARDS": "REC_YDS", "REC": "RECEPTIONS", "RECEPTION": "RECEPTIONS"}
TIPOS_PROP = ("PROP", "PLAYER", "PLAYER PROP", "PLAYER PROPS", "PROPS", "PLAYER TDS", "PLAYER STATS", "PLAYER TD")


def _norm_nombre(x):
    x = unicodedata.normalize("NFKD", str(x or "")).encode("ascii", "ignore").decode().lower().replace("-", " ")
    return [w for w in re.sub(r"[^a-z ]", " ", x).split() if w not in ("jr", "sr", "ii", "iii", "iv", "v")]


def mismo_jugador(a, b):
    """'W. Lutz' = 'Wil Lutz' · 'J. Smith-Njigba' = 'Jaxon Smith-Njigba' (apellido igual e inicial del nombre igual)."""
    ta, tb = _norm_nombre(a), _norm_nombre(b)
    if not ta or not tb:
        return False
    if ta == tb:
        return True
    return len(ta) >= 2 and len(tb) >= 2 and ta[1:] == tb[1:] and ta[0][0] == tb[0][0]


def stats_jugadores(res):
    """{nombre en ESPN: {clave: valor}} del boxscore del resumen de ESPN; None si todavía no hay estadísticas."""
    jug = {}
    for t_ in ((res or {}).get("boxscore") or {}).get("players") or []:
        for s in t_.get("statistics") or []:
            keys = s.get("keys") or []
            for a in s.get("athletes") or []:
                nom = (a.get("athlete") or {}).get("displayName") or ""
                if not nom:
                    continue
                d = jug.setdefault(nom, {})
                for k, v in zip(keys, a.get("stats") or []):
                    if k == "fieldGoalsMade/fieldGoalAttempts":
                        v = str(v).split("/")[0]
                    try:
                        d[k] = d.get(k, 0.0) + float(str(v).replace(",", ""))
                    except (TypeError, ValueError):
                        pass
    return jug or None


def buscar_jugador(jug, nombre):
    """(nombre en ESPN, estadísticas) o (None, None). Primero nombre e inicial; si no, el apellido, solo si es único."""
    if not jug or not nombre:
        return None, None
    exactos = [n for n in jug if mismo_jugador(n, nombre)]
    if len(exactos) == 1:
        return exactos[0], jug[exactos[0]]
    tn = _norm_nombre(nombre)
    cand = [n for n in jug if tn and _norm_nombre(n)[-1:] == tn[-1:]]
    if len(cand) == 1:
        return cand[0], jug[cand[0]]
    return None, None


def valor_prop(p, res):
    """(valor de la estadística, nombre en ESPN); (None, None) si no hay resumen o el jugador no aparece."""
    nom, d = buscar_jugador(stats_jugadores(res), p.get("jugador"))
    if d is None:
        return None, None
    return float(sum(d.get(k, 0.0) for k in PROP_STATS.get(p.get("stat"), ((),))[0])), nom


def prob_prop(p, juego, res):
    """(pg, pp, valor). Antes del juego: sin probabilidad (no hay línea gratuita de props). En juego: decidida solo si ya
    pasó la línea (gana el over, pierde el under). Terminado: 1/0 o push; si el jugador no aparece en ESPN, cuenta 0."""
    if juego["estado"] == "pre" or juego.get("cancelado"):
        return None, None, None
    v, _ = valor_prop(p, res)
    if v is None:
        if juego["estado"] != "post" or stats_jugadores(res) is None:
            return None, None, None
        v = 0.0
    linea = float(p.get("linea") if p.get("linea") is not None else 0.5)
    over = p.get("lado", "OVER") == "OVER"
    if juego["estado"] != "post":
        if v > linea:
            return (1.0, 0.0, v) if over else (0.0, 0.0, v)
        return None, None, v
    if abs(v - linea) < 1e-9:
        return 0.0, 1.0, v
    return (1.0, 0.0, v) if (v > linea) == over else (0.0, 0.0, v)


def leer_prop(p):
    """dict(jugador, stat, linea, lado) de una pata de prop leída por Gemini; si faltan campos, del texto del boleto
    («Bo Nix Score Anytime (Game)», «W. Lutz 2+ Field Goals (Game)», «S. Darnold Under 1.5 Passing TDs»). None si no es un prop."""
    txt = str(p.get("texto") or "")
    t_ = normal(txt)
    st = re.sub(r"[\s\-/]+", "_", str(p.get("estadistica") or p.get("stat") or "").upper().strip())
    st = ALIAS_STAT.get(st, st)
    if st not in PROP_STATS:
        st = ("PASS_TD" if re.search(r"passing (td|touchdown)", t_) else
              "FG" if "field goal" in t_ else
              "PASS_YDS" if "passing yard" in t_ else
              "RUSH_YDS" if "rushing yard" in t_ else
              "REC_YDS" if "receiving yard" in t_ else
              "RECEPTIONS" if "reception" in t_ else
              "TD" if re.search(r"anytime|score|touchdown scorer|to score", t_) else None)
    if st is None:
        return None
    linea, lado = _linea(p.get("linea")), str(p.get("lado") or "").upper()
    lado = "UNDER" if ("UNDER" in lado or re.search(r"\bunder\b", t_)) else "OVER"
    if linea is None:
        m = re.search(r"(\d+)\s*\+", t_)
        n = re.search(r"\b(?:over|under|o|u)\s*(\d+(?:\.\d+)?)", t_)
        linea = (int(m.group(1)) - 0.5) if m else (float(n.group(1)) if n else 0.5)
    jugador = str(p.get("jugador") or "").strip()
    txt = re.sub(r"^\s*(?:player\s+(?:tds?|touchdowns|stats|props)|props?)\s*[-–:]\s*", "", txt, flags=re.I)
    if not jugador:
        jugador = re.split(r"\s(?:\d+\s*\+|over\b|under\b|score\b|anytime\b|to score\b|passing\b|rushing\b|receiving\b|receptions?\b|field goals?\b)",
                          txt, maxsplit=1, flags=re.I)[0].strip(" -·:")
    return dict(jugador=jugador, stat=st, linea=float(linea), lado=lado)


def prop_txt(p):
    """«Bo Nix anota TD» · «W. Lutz 2+ goles de campo» · «S. Darnold menos de 1½ pases de TD» · «X más de 249½ yardas de pase»."""
    st = PROP_STATS.get(p.get("stat"))
    jug = p.get("jugador") or "?"
    if not st:
        return f"{jug}: {p.get('texto') or 'prop'}"
    linea = float(p.get("linea") if p.get("linea") is not None else 0.5)
    over = p.get("lado", "OVER") == "OVER"
    if p["stat"] == "TD" and over and abs(linea - 0.5) < 1e-9:
        return f"{jug} anota TD"
    if over and p["stat"] not in YARDAS and abs(linea - math.floor(linea) - 0.5) < 1e-9:
        n = int(linea + 0.5)
        return f"{jug} {n}+ {st[1] if n == 1 else st[2]}"
    return f"{jug} {'más' if over else 'menos'} de {media_txt(linea)} {st[2]}"


def umbral_txt(p):
    """«1 o más» · «1 o menos» · «más de 224½» (yardas)."""
    linea = float(p.get("linea") if p.get("linea") is not None else 0.5)
    over = p.get("lado", "OVER") == "OVER"
    if p.get("stat") in YARDAS or abs(linea - math.floor(linea) - 0.5) > 1e-9:
        return f"{'más' if over else 'menos'} de {media_txt(linea)}"
    return f"{int(math.floor(linea)) + 1} o más" if over else f"{int(math.floor(linea))} o menos"


def avance_prop(p, j):
    v = p.get("_valor")
    st = PROP_STATS.get(p.get("stat"), ((), "", ""))
    if v is None:
        return "sin estadísticas todavía" if j["estado"] != "post" else "sin datos de ESPN"
    linea = float(p.get("linea") if p.get("linea") is not None else 0.5)
    over = p.get("lado", "OVER") == "OVER"
    lleva = f"{num_txt(v)} {st[1] if abs(v - 1) < 1e-9 else st[2]}"
    if j["estado"] == "post":
        r = "push" if abs(v - linea) < 1e-9 else ("ganada" if (v > linea) == over else "perdida")
        return f"terminó con {lleva}: {r}"
    if over:
        falta = math.floor(linea) + 1 - v
        return f"lleva {lleva}; " + ("ya la ganó" if v > linea else f"le falta{'n' if falta > 1 else ''} {num_txt(falta)}")
    necesita = math.floor(linea) + 1 - v
    return f"lleva {lleva}; " + ("ya se pasó" if v > linea else f"se pierde con {num_txt(necesita)} más")


# ---------------------------------------------------------------- textos de una pata
def nombre_pata(p):
    c = americana_txt(p.get("cuota"))
    if p.get("tipo") == "PROP":
        return f"{prop_txt(p)} {c}".strip()
    if p["tipo"] == "ML":
        return f"{p['equipo']} ML {c}".strip()
    if p["tipo"] == "SPREAD":
        return f"{p['equipo']} {linea_txt(p['linea'])} {c}".strip()
    lado = "Over" if p.get("lado_total", "OVER") == "OVER" else "Under"
    return f"{lado} {fi(p['linea'])} ({p.get('partido', '')}) {c}".strip()


def pata_corta(p):
    """v1.3.1, para la hoja y el histórico: «Bills ML», «Texans −2½», «Over 44½ (NE @ BUF)», sin la cuota."""
    if p.get("tipo") in ("ML", "SPREAD"):
        eq = APODO_EQ.get(p.get("equipo") or "", p.get("equipo") or "?")
        return f"{eq} ML" if p["tipo"] == "ML" else f"{eq} {linea_eq_txt(p.get('linea'))}"
    if p.get("tipo") == "TOTAL":
        lado = "Over" if p.get("lado_total", "OVER") == "OVER" else "Under"
        return f"{lado} {media_txt(p.get('linea'))}" + (f" ({p['partido']})" if p.get("partido") else "")
    if p.get("tipo") == "PROP":
        return prop_txt(p)
    return str(p.get("texto") or "?")[:40]


def marcador_txt(j):
    v, l = j["visita"], j["local"]
    if j["estado"] == "pre":
        return f"{v.get('abbr')} @ {l.get('abbr')}"
    cu = {1: "1.º", 2: "2.º", 3: "3.º", 4: "4.º"}.get(j.get("periodo", 0), "TE")
    reloj = "final" if j["estado"] == "post" else ("medio tiempo" if "half" in (j.get("detalle") or "").lower() else f"{cu} {j.get('reloj', '')}")
    return f"{v.get('abbr')} {v.get('puntos')} - {l.get('puntos')} {l.get('abbr')} · {reloj}"


def avance_txt(p, j):
    """Cómo va la pata en palabras (sin probabilidad)."""
    loc, vis = j["local"].get("puntos", 0), j["visita"].get("puntos", 0)
    if j.get("cancelado"):
        return "juego suspendido"
    if j["estado"] == "pre":
        return f"{hora_ccs(j['inicio'])} (Caracas)"
    if p.get("tipo") == "PROP":
        return avance_prop(p, j)
    if p["tipo"] in ("ML", "SPREAD"):
        dif = (loc - vis) if p["equipo"] == j["local"].get("abbr") else (vis - loc)
        v = dif + (0 if p["tipo"] == "ML" else float(p["linea"]))
        if j["estado"] == "post":
            return "ganada" if v > 0 else "push" if v == 0 else "perdida"
        if p["tipo"] == "ML":
            return f"va ganando por {dif}" if dif > 0 else "empatado" if dif == 0 else f"va perdiendo por {-dif}"
        return f"cubre por {num_txt(abs(v))}" if v > 0 else "justo en el número" if v == 0 else f"le faltan {num_txt(abs(v))}"
    tot, linea = loc + vis, float(p["linea"])
    over = p.get("lado_total", "OVER") == "OVER"
    if j["estado"] == "post":
        return "push" if tot == linea else ("ganada" if (tot > linea) == over else "perdida")
    necesita = math.floor(linea) + 1 - tot
    if over:
        return f"van {tot}; ya pasó la línea" if necesita <= 0 else f"van {tot}; faltan {necesita} puntos"
    return f"van {tot}; se pierde con {necesita} puntos más" if necesita > 0 else f"van {tot}; ya se pasó"


def estado_marcador(p, j):
    """v1.3.2 (42m): cómo va la pata según el marcador: 'gana', 'pierde' o 'igual'. ML y spread: el marcador (con la línea
    en el spread). Totales: el ritmo (los puntos que van, llevados al partido completo, contra la línea); con menos del 10 %
    del partido jugado, 'igual'."""
    loc, vis = j["local"].get("puntos", 0) or 0, j["visita"].get("puntos", 0) or 0
    if p.get("tipo") == "PROP":                       # v1.4: el over va perdiendo hasta que pasa la línea
        if p.get("_valor") is None:
            return "igual"
        v = p["_valor"] - float(p.get("linea") if p.get("linea") is not None else 0.5)
        if p.get("lado", "OVER") != "OVER":
            v = -v
        return "gana" if v > 1e-9 else "pierde" if v < -1e-9 else "igual"
    if p["tipo"] in ("ML", "SPREAD"):
        dif = (loc - vis) if p["equipo"] == j["local"].get("abbr") else (vis - loc)
        v = dif + (0 if p["tipo"] == "ML" else float(p["linea"]))
    else:
        jugado = 1.0 - fraccion_restante(j)
        if jugado < 0.1:
            return "igual"
        v = (loc + vis) / jugado - float(p["linea"])
        if p.get("lado_total", "OVER") != "OVER":
            v = -v
    return "gana" if v > 1e-9 else "pierde" if v < -1e-9 else "igual"


def icono(j, pg, pp, p=None):
    """⏳ antes del juego · ✅ ❌ 🟡 terminado · en vivo (v1.3.2, 42m) el color sigue al marcador: 🟢 va ganando (o
    cubriendo; en totales, a ese ritmo), 🔴 va perdiendo, ⚪ empatado o justo en el número. La probabilidad va aparte,
    en palabras (prob_txt)."""
    if j.get("cancelado"):
        return "⚪"
    if j["estado"] == "pre":
        return "⏳"
    if j["estado"] == "post":
        return "✅" if pg == 1.0 else "🟡" if pp == 1.0 else "❌"
    if p is None:
        return "⚪"
    return {"gana": "🟢", "pierde": "🔴"}.get(estado_marcador(p, j), "⚪")


def prob_txt(p, prob, est):
    """v1.3.2 (42m): la probabilidad en palabras: «todavía la gana 53 de cada 100»."""
    k = int(round(100 * prob))
    if p["tipo"] == "ML":
        verbo = "la gana"
    elif p["tipo"] == "SPREAD":
        verbo = "la cubre"
    else:
        verbo = "la pasa" if p.get("lado_total", "OVER") == "OVER" else "termina debajo"
    return ("todavía " if est == "pierde" else "") + f"{verbo} {k} de cada 100"


def situacion_txt(j, ev):
    if j["estado"] != "in" or not ev.get("pos"):
        return ""
    d, dist, yte = ev.get("down"), ev.get("dist"), ev.get("yte")
    if d not in (1, 2, 3, 4):
        return f"balón: {ev['pos']} (patada)"
    rival = j["local"]["abbr"] if ev["pos"] == j["visita"]["abbr"] else j["visita"]["abbr"]
    donde = ""
    if yte is not None and 1 <= int(yte) <= 99:
        yte = int(yte)
        donde = f" en su {100 - yte}" if yte > 50 else (" en el medio campo" if yte == 50 else f" en la {yte} de {rival}")
    return f"balón: {ev['pos']}, {d}.º y {dist}{donde}" + (" (zona roja)" if yte is not None and int(yte) <= 20 else "")


# ---------------------------------------------------------------- boletos
def p_cobrar(probs):
    out = 1.0
    for pg, pp in probs:
        if pg is None:
            return None
        out *= pg + pp
    return out


def ev_boleto(b, probs):
    """EV por unidad. Parlay: semana.parlay (Π(p·D + push) − 1) con la cuota de cada pata; si falta alguna, con el pago
    del boleto. Teaser: el pago del boleto con todas; un push baja un nivel (tabla con recargo de semana.py)."""
    if not probs or any(pg is None for pg, _ in probs):
        return None
    patas = b["patas"]
    if b.get("tipo") == "TEASER":
        n = len(patas)
        dp = [1.0] + [0.0] * n
        for pg, pq in probs:
            nuevo = [0.0] * (n + 1)
            for k in range(n + 1):
                if dp[k]:
                    nuevo[k] += dp[k] * pg
                    if k < n:
                        nuevo[k + 1] += dp[k] * pq
            dp = nuevo
        D_n = (b["pago"] / b["monto"]) if b.get("pago") and b.get("monto") else S.decimal(S.TEASER_PAGOS.get(n, 600))
        cap = TOPE_PAGO / b["monto"] if b.get("monto") else float("inf")     # v1.5: tope de pago (premisa 3)
        R = 0.0
        for k, pk in enumerate(dp):
            m = n - k
            R += pk * min(cap, D_n if k == 0 else 1.0 if (n == 2 or m <= 1) else S.decimal(S.TEASER_PAGOS[m]))
        return R - 1
    if all(p.get("cuota") for p in patas):
        return ev_parlay_tope(probs, [S.decimal(p["cuota"]) for p in patas], b.get("monto"))
    if b.get("pago") and b.get("monto"):
        return p_cobrar([(pg, 0.0) for pg, _ in probs]) * min(b["pago"], TOPE_PAGO) / b["monto"] - 1
    return None


def ev_parlay_tope(probs, decs, monto):
    """v1.5: EV por unidad de un parlay con las cuotas de cada pata: Π(p·D + push) − 1 (una pata empatada sale del parlay),
    con el tope de pago de BetOnline (premisa 3). Si el pago completo no llega al tope, es exactamente semana.parlay."""
    base = S.parlay([(pg, pp, d) for (pg, pp), d in zip(probs, decs)])["ev"]
    total = 1.0
    for d in decs:
        total *= d
    if not monto or monto * total <= TOPE_PAGO:
        return base
    cap = TOPE_PAGO / monto
    con_push = [i for i, (_, pp) in enumerate(probs) if (pp or 0) > 0]
    if len(con_push) > 14:                     # demasiadas combinaciones: el empate se cuenta como ganada (aproximación)
        p_pata, con_push = [pg + (pp or 0) for pg, pp in probs], []
    else:
        p_pata = [pg for pg, _ in probs]
    p0, d0 = 1.0, 1.0
    for i in range(len(probs)):
        if i not in con_push:
            p0 *= p_pata[i]
            d0 *= decs[i]
    R = 0.0
    for mascara in range(1 << len(con_push)):
        p, d = p0, d0
        for j, i in enumerate(con_push):
            if mascara >> j & 1:
                p *= probs[i][1]
            else:
                p *= probs[i][0]
                d *= decs[i]
        R += p * min(d, cap)
    return R - 1


def cuadra_pago(b):
    """Diferencia relativa entre el pago del boleto y monto × Π cuotas (control de la lectura); None si no se puede."""
    patas = b.get("patas", [])
    if b.get("tipo") != "PARLAY" or not b.get("monto") or not b.get("pago") or not patas or not all(p.get("cuota") for p in patas):
        return None
    prod = 1.0
    for p in patas:
        prod *= S.decimal(p["cuota"])
    esp = b["monto"] * prod
    return min(abs(esp - b["pago"]), abs(esp - b["monto"] - b["pago"])) / esp


def pago_vigente(b):
    """v1.5 (v1.3.3): el pago que corresponde hoy. Con patas empatadas (res «E») BetOnline las saca del boleto (premisa 3):
    el parlay paga pago ÷ Π(cuota decimal de las empatadas); el teaser baja un nivel de la tabla (en 2 patas, o si queda
    una, devuelve lo apostado). Siempre con el tope de USD 150.000. Devuelve (pago, nota); nota vacía si no cambió."""
    pago, monto = b.get("pago"), b.get("monto")
    if not pago:
        return pago, ""
    emp = [p for p in b.get("patas", []) if p.get("res") == "E"]
    nota = ""
    if emp:
        n, m = len(b["patas"]), len(b["patas"]) - len(emp)
        if b.get("tipo") == "TEASER":
            nuevo = monto if (n == 2 or m <= 1) else (monto * S.decimal(S.TEASER_PAGOS.get(m, 600)) if monto else None)
        elif m == 0:
            nuevo = monto
        elif all(p.get("cuota") for p in emp):
            nuevo = pago
            for p in emp:
                nuevo /= S.decimal(p["cuota"])
        else:
            nuevo = None
        e = f"{len(emp)} empate{'s' if len(emp) != 1 else ''}"
        if nuevo:
            nota, pago = f"bajó por {e}; era {dinero(b.get('pago'))}", nuevo
        else:
            nota = f"baja por {e}; no leí la cuota para calcularlo"
    if pago and pago > TOPE_PAGO:
        nota = (nota + "; " if nota else "") + f"tope de BetOnline USD 150.000; el boleto dice {dinero(b.get('pago'))}"
        pago = TOPE_PAGO
    return pago, nota


def pago_txt(b):
    pago, nota = pago_vigente(b)
    return dinero(pago) + (f" ({nota})" if nota else "")


def _menciona(txt, eq):
    """¿El texto nombra a este equipo? Los apodos son únicos en la NFL (Jets, Giants, Rams, Chargers…)."""
    if not eq:
        return False
    t = f" {txt} "
    apodo = normal(eq.get("apodo", "")).strip()
    if apodo and re.search(rf"\b{re.escape(apodo)}\b", t):
        return True
    ab = normal(eq.get("abbr", "")).strip()
    alias = {"la": ["lar"], "was": ["wsh"], "lv": ["oakland"]}
    return any(a and re.search(rf"(^|\s){re.escape(a)}(\s|$)", t) for a in [ab] + alias.get(ab, []))


def limpiar_nombre(x):
    """Nombre que puso Ozz: sin espacios de más, sin «/» al inicio, máximo NOMBRE_MAX letras. '' si no sirve."""
    x = re.sub(r"\s+", " ", str(x or "")).strip().lstrip("/").strip()
    return x[:NOMBRE_MAX].strip()


def nombre_de(b):
    """Nombre del boleto guardado; los de v1-v1.2 no tienen: «Parlay 3», «Teaser 4»…"""
    return b.get("nombre") or f"{(b.get('tipo') or 'parlay').capitalize()} {b.get('id', '')}".strip()


def _clave_nombre(x):
    return re.sub(r"\s+", " ", normal(x)).strip()


def normalizar(lista):
    """v1.3.1 (42j). Cada boleto lleva su semana (temporada, fase, semana de ESPN) y su número dentro de la semana (n).
    Los de v1-v1.3 se numeran por semana en el orden en que se cargaron (1, 2, 3…); los borrados quedan con n = 0. Su
    nombre automático con el número global («Parlay 7») pasa al de la semana («Parlay 2»); los nombres que puso Ozz no
    cambian. Idempotente: lo ya numerado no se toca."""
    porsem = {}
    for b in sorted(lista, key=lambda x: x.get("id", 0)):
        b.setdefault("fase", 2)
        porsem.setdefault(clave_semana(b), []).append(b)
    for bs in porsem.values():
        tope = max([b.get("n") or 0 for b in bs if b.get("estado") != "borrado"], default=0)
        for b in bs:
            if b.get("n") is not None:
                continue
            if b.get("estado") == "borrado":
                b["n"] = 0
            else:
                tope += 1
                b["n"] = tope
            if "nombre_auto" not in b:
                auto = not b.get("nombre") or _clave_nombre(b["nombre"]) == _clave_nombre(f"{b.get('tipo') or 'parlay'} {b.get('id', '')}")
                b["nombre_auto"] = bool(auto)
                if auto and b["n"]:
                    b["nombre"] = f"{(b.get('tipo') or 'parlay').capitalize()} {b['n']}"
    return lista


def aciertos_boleto(b):
    """v1.3.2: aciertos de un parlay contados desde sus patas (no desde el momento en que el boleto se cerró)."""
    ps = b.get("patas", [])
    dec = [p for p in ps if p.get("res") in ("G", "P", "E")]
    return dict(aciertos=sum(1 for p in dec if p["res"] == "G"), decididas=len(dec), total=len(ps), faltan=len(ps) - len(dec),
                esperados=round(sum(p.get("p_cierre") or 0.0 for p in dec), 2))


def aciertos_txt(b, mayuscula=False):
    a = aciertos_boleto(b)
    txt = (f"acertó {a['aciertos']} de {a['decididas']} patas" + (f" (faltan {a['faltan']} por jugar)" if a["faltan"] else "")
           if a["decididas"] else "todavía no se jugó ninguna pata")
    return txt[:1].upper() + txt[1:] if mayuscula else txt


def resumen_semana(bs):
    """Aciertos contra lo esperado (probabilidad de ganar al cierre de cada pata ya jugada) y causas de las perdidas."""
    out = dict(aciertos=0, decididas=0, esperados=0.0, perdidas=0, causas={}, sin_razon=0)
    for b in bs:
        for p in b.get("patas", []):
            if p.get("res") not in ("G", "P", "E"):
                continue
            out["decididas"] += 1
            out["aciertos"] += p["res"] == "G"
            out["esperados"] += p.get("p_cierre") or 0.0
            if p["res"] == "P":
                out["perdidas"] += 1
                pq = p.get("por_que")
                if not pq:
                    out["sin_razon"] += 1
                for c in (pq or {}).get("causas", []):
                    out["causas"][c] = out["causas"].get(c, 0) + 1
    return out


def causas_txt(causas):
    orden = sorted(causas.items(), key=lambda kv: (-kv[1], list(CAUSAS).index(kv[0]) if kv[0] in CAUSAS else 99))
    return " · ".join(f"{CAUSAS.get(c, c)} {n}" for c, n in orden)


def texto_por_que(p):
    pq = p.get("por_que")
    if pq and pq.get("texto"):
        return pq["texto"]
    return "sale cuando nflverse publique la jugada por jugada (suele ser al día siguiente del partido)."


def hoja_parlays_id():
    import configparser
    c = configparser.ConfigParser()
    if S.CONFIG.exists():
        c.read(S.CONFIG)
    return (c.get("parlays", "hoja_id", fallback="") or HOJA_PARLAYS_ID).strip()


class Parlays:
    def __init__(self, espn=None, bot_dir=BOT_DIR, ahora=None):
        self.espn = espn or ESPN()
        self.bot_dir = bot_dir
        self.ahora = ahora or ahora_utc()
        self._cal = None
        self._refs = {}

    # -- calendario de nflverse (semana.py lo refresca cada hora)
    def cal(self):
        if self._cal is None:
            _, g26 = S.calendario(1.0)
            self._cal = {(r["season"], r["week"], frozenset((r["home_team"], r["away_team"]))): r for r in g26.iter_rows(named=True)}
        return self._cal

    def fila_nfl(self, j):
        sem = semana_nflverse(j.get("fase", 2), j.get("semana"))
        return self.cal().get((j.get("temporada"), sem, frozenset((j["local"].get("abbr"), j["visita"].get("abbr")))))

    def fila_de_pata(self, b, p):
        """Fila de nflverse del juego de una pata guardada (por la semana del boleto y los equipos de «VIS @ LOC»)."""
        eqs = [x.strip() for x in str(p.get("partido") or "").split("@")]
        if len(eqs) != 2 or not all(eqs):
            return None
        t, f, s = clave_semana(b)
        return self.cal().get((t, semana_nflverse(f, s), frozenset(eqs)))

    def semana_actual(self):
        """(temporada, fase, semana) de ESPN ahora (la que muestra su tablero); si ESPN no responde, la de nflverse."""
        if getattr(self, "_actual", None) is None:
            try:
                tab = self.espn.tablero()
                self._actual = (int((tab.get("season") or {}).get("year") or S.TEMPORADA), int((tab.get("season") or {}).get("type") or 2),
                                int((tab.get("week") or {}).get("number") or 0))
            except Exception:  # noqa: BLE001
                try:
                    _, g26 = S.calendario(6.0)
                    s = S.semana_actual(g26, self.ahora)
                    self._actual = (S.TEMPORADA, 3 if s and s > 18 else 2,
                                    next((k for k, v in PLAYOFFS_ESPN.items() if v[1] == s), s) if s and s > 18 else (s or 0))
                except BaseException:  # noqa: BLE001
                    self._actual = (S.TEMPORADA, 2, 0)
        return self._actual

    def ref(self, j, cierre=False):
        clave = (j["id"], cierre)
        if clave not in self._refs:
            f = self.fila_nfl(j)
            self._refs[clave] = Referencia(f, self.ahora, cierre=cierre, bot_dir=self.bot_dir) if f else None
        return self._refs[clave]

    # -- registro
    def todos(self):
        """El registro, con la numeración por semana de v1.3.1 (normalizar; se guarda en la próxima escritura).
        Si el archivo existe pero no se puede leer, falla (nunca se reescribe un registro dañado con una lista vacía)."""
        if REGISTRO.exists():
            try:
                lista = json.loads(REGISTRO.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError) as e:
                raise RuntimeError(f"no puedo leer {REGISTRO.name} ({type(e).__name__}); no escribo nada") from e
            if not isinstance(lista, list):
                raise RuntimeError(f"{REGISTRO.name} no tiene la forma esperada; no escribo nada")
            return normalizar(lista)
        return []

    def _guardar(self, lista):
        for b in lista:                                  # v1.4: «_valor» es solo de pantalla
            for p in b.get("patas") or []:
                p.pop("_valor", None)
        _guardar_json(REGISTRO, lista)

    def de_semana(self, clave, lista=None, con_borrados=False):
        return sorted([b for b in (lista if lista is not None else self.todos())
                       if clave_semana(b) == clave and (con_borrados or b.get("estado") != "borrado")], key=lambda b: (b.get("n") or 0, b["id"]))

    def _juegos(self, semana=None, temporada=None, ids=(), fase=2):
        out = {j["id"]: j for j in juegos_del_tablero(self.espn.tablero(semana, temporada, fase))}
        if set(ids) - set(out):
            for j in juegos_del_tablero(self.espn.tablero()):
                out.setdefault(j["id"], j)
        return out

    def juegos_de(self, b):
        return self._juegos(b.get("semana"), b.get("temporada"), [p.get("evento") for p in b["patas"]], b.get("fase") or 2)

    # -- probabilidades de un boleto: 'ahora' (en vivo), 'previa' (línea vigente) o 'cierre'
    def filas(self, b, juegos, modo="ahora", con_resumen=False):
        out, resumenes = [], {}
        for p in b["patas"]:
            j = juegos.get(p.get("evento"))
            if not j:
                out.append(dict(p=p, j=None, pg=None, pp=None, res=None))
                continue
            if p.get("tipo") == "PROP":                   # v1.4 (42n): ESPN; sin probabilidad antes ni al cierre
                if modo != "ahora" or j["estado"] == "pre":
                    out.append(dict(p=p, j=j, pg=None, pp=None, res=None, fuente="sin línea de props"))
                    continue
                if j["id"] not in resumenes:
                    try:
                        resumenes[j["id"]] = self.espn.resumen(j["id"])
                    except Exception:  # noqa: BLE001
                        resumenes[j["id"]] = None
                res = resumenes[j["id"]]
                pg, pp, v = prob_prop(p, j, res)
                p["_valor"] = v
                out.append(dict(p=p, j=j, pg=pg, pp=pp, res=res if j["estado"] == "in" else None, res_final=res, fuente="ESPN (props)"))
                continue
            if modo == "ahora" and j["estado"] != "pre":
                res = None
                if con_resumen and j["estado"] == "in":
                    try:
                        res = self.espn.resumen(j["id"])
                    except Exception:  # noqa: BLE001
                        res = None
                r = self.ref(j, cierre=True)
                if r is None or not r.ok():
                    r = self.ref(j)
                pg, pp = prob_vivo(p, j, r, res) if r is not None else (None, None)
                out.append(dict(p=p, j=j, pg=pg, pp=pp, res=res))
                continue
            r = self.ref(j, cierre=(modo == "cierre" and j["estado"] != "pre"))
            if r is None or not r.ok():
                r = self.ref(j)
            pg, pp = prob_previa(p, r) if r is not None else (None, None)
            out.append(dict(p=p, j=j, pg=pg, pp=pp, res=None, fuente=r.fuente if r else "sin juego"))
        return out

    # -- carga desde la lectura de Gemini
    def cruzar(self, lectura, juegos):
        patas, avisos = [], []
        for i, p in enumerate(lectura.get("patas", []), 1):
            tipo = (p.get("tipo") or "").upper().strip()
            tipo = {"MONEYLINE": "ML", "PUNTOS": "SPREAD", "HANDICAP": "SPREAD", "OVER/UNDER": "TOTAL"}.get(tipo, tipo)
            prop = None
            if tipo in TIPOS_PROP or tipo not in ("ML", "SPREAD", "TOTAL"):      # v1.4 (42n)
                prop = leer_prop(p)
                if prop:
                    tipo = "PROP"
            txt_eq = normal(p.get("equipo") or p.get("texto") or "")
            txt_todo = normal(" ".join(str(p.get(k) or "") for k in ("equipo", "partido", "texto")))
            juego, equipo = None, None
            if tipo == "PROP":
                cand = [j for j in juegos if _menciona(txt_todo, j["local"]) and _menciona(txt_todo, j["visita"])] or \
                       [j for j in juegos if _menciona(txt_todo, j["local"]) or _menciona(txt_todo, j["visita"])]
                juego = cand[0] if len(cand) == 1 else None
            elif tipo in ("ML", "SPREAD"):
                cand = [(j, s) for j in juegos for s in ("local", "visita") if _menciona(txt_eq, j[s])]
                if len(cand) == 1:
                    juego, equipo = cand[0][0], cand[0][0][cand[0][1]]["abbr"]
            elif tipo == "TOTAL":
                cand = [j for j in juegos if _menciona(txt_todo, j["local"]) and _menciona(txt_todo, j["visita"])] or \
                       [j for j in juegos if _menciona(txt_todo, j["local"]) or _menciona(txt_todo, j["visita"])]
                juego = cand[0] if len(cand) == 1 else None
            linea = _linea(p.get("linea"))
            lado = (p.get("lado") or "").upper()
            pata = dict(k=i, tipo=tipo, equipo=equipo, linea=0.0 if tipo == "ML" else linea, cuota=_entero(p.get("cuota")),
                        lado_total=("UNDER" if ("UNDER" in lado or "under" in normal(p.get("texto"))) else "OVER") if tipo == "TOTAL" else None,
                        evento=juego["id"] if juego else None,
                        partido=f"{juego['visita']['abbr']} @ {juego['local']['abbr']}" if juego else "",
                        inicio=juego["inicio"] if juego else None, texto=p.get("texto") or "")
            if prop:
                pata.update(prop, linea=prop["linea"])
            if tipo not in ("ML", "SPREAD", "TOTAL", "PROP"):
                avisos.append(f"pata {i}: tipo «{p.get('tipo')}» no reconocido")
            elif not juego and tipo != "PROP":
                avisos.append(f"pata {i}: no encontré el juego de «{p.get('texto') or p.get('equipo')}» en el calendario de esta semana")
            if tipo in ("SPREAD", "TOTAL") and linea is None:
                avisos.append(f"pata {i}: falta la línea")
            patas.append(pata)
        # v1.4 (42n): un prop sin juego toma el del resto del boleto si todas sus patas son de un solo juego
        ids = {p["evento"] for p in patas if p.get("evento")}
        por_id = {j["id"]: j for j in juegos}
        for p in patas:
            if p["tipo"] != "PROP" or p.get("evento"):
                continue
            if len(ids) == 1 and next(iter(ids)) in por_id:
                j = por_id[next(iter(ids))]
                p.update(evento=j["id"], partido=f"{j['visita']['abbr']} @ {j['local']['abbr']}", inicio=j["inicio"])
            else:
                avisos.append(f"pata {p['k']}: no encontré el juego de «{p.get('texto') or p.get('jugador')}» en el calendario de esta semana")
        return patas, avisos

    def preparar_uno(self, lectura, lista, tab, archivo=None):
        patas, avisos = self.cruzar(lectura, lista)
        tipo = (lectura.get("tipo") or "").upper()
        tipo = "TEASER" if "TEASER" in tipo else "PARLAY" if ("PARLAY" in tipo or len(patas) > 1) else "SENCILLA"
        b = dict(tipo=tipo, monto=_num(lectura.get("monto")), pago=_num(lectura.get("pago")), numero=str(lectura.get("numero") or "").strip(),
                 patas=patas, foto=archivo, lectura=lectura, semana=(tab.get("week") or {}).get("number"),
                 temporada=(tab.get("season") or {}).get("year"), fase=int((tab.get("season") or {}).get("type") or 2))
        juegos = {j["id"]: j for j in lista}
        fil = self.filas(b, juegos, modo="previa")
        probs = [(f["pg"], f["pp"]) for f in fil]
        for f in fil:                     # v1.3.1: probabilidad de cada pata al cargarla (para la hoja)
            f["p"]["p_carga"] = None if f["pg"] is None else round(f["pg"], 4)
        pc, ev = p_cobrar(probs), ev_boleto(b, probs)
        b["previo"] = dict(p_cobrar=pc, ev=ev, costo=None if ev is None or not b["monto"] else -ev * b["monto"],
                           hora=S.iso(self.ahora), fuentes=sorted({f.get("fuente", "") for f in fil if f.get("fuente")}))
        d = cuadra_pago(b)
        if d is not None and d > 0.03:
            avisos.append(f"el pago no cuadra con las cuotas que leí (diferencia {pct(d)}): revisa montos y cuotas")
        if not b["monto"] or not b["pago"]:
            avisos.append("no leí el monto o el pago: el EV y el costo quedan incompletos")
        if any(p["tipo"] == "PROP" for p in patas):
            avisos.append("props de jugador: no hay línea de mercado gratuita, así que no hay P(cobrar) ni EV; "
                          "el bot las sigue en vivo y las liquida con ESPN")
        por_juego = {}
        for p in patas:
            if p.get("evento"):
                por_juego.setdefault(p["evento"], []).append(p["k"])
        for ks in por_juego.values():
            if len(ks) > 1:
                avisos.append(f"patas {', '.join(map(str, ks))} del mismo juego: la P(cobrar) las trata como independientes")
        empezados = [f["p"]["k"] for f in fil if f["j"] and f["j"]["estado"] != "pre"]
        if empezados:
            avisos.append("patas con el juego ya empezado o terminado: " + ", ".join(map(str, empezados)))
        return b, avisos, fil

    def preparar(self, lectura, archivo=None, nombre=None):
        """lectura: {"boletos": [...]} (v1.1) o un solo boleto (v1). Deja todos pendientes hasta /si.
        nombre (v1.3): el que eligió Ozz; con varios boletos se numeran (Domingo 1, Domingo 2…)."""
        tab = self.espn.tablero()
        lista = juegos_del_tablero(tab)
        lecturas = lectura.get("boletos") if isinstance(lectura.get("boletos"), list) else [lectura]
        lecturas = [x for x in lecturas if isinstance(x, dict) and x.get("patas")][:MAX_BOLETOS]
        hechos = [self.preparar_uno(x, lista, tab, archivo) for x in lecturas]
        if not hechos:
            return "No encontré ningún boleto con patas. Mándamelo otra vez con todas las patas a la vista."
        nombre = limpiar_nombre(nombre)
        for i, (b, _, _) in enumerate(hechos, 1):
            if nombre:
                b["nombre"] = nombre if len(hechos) == 1 else f"{nombre} {i}"
        _guardar_json(PENDIENTE, dict(boletos=[h[0] for h in hechos], avisos=[h[1] for h in hechos], creado=S.iso(self.ahora)))
        partes = [self.texto_pendiente(b, av, fil, rotulo=(f"«{b['nombre']}»" if b.get("nombre") and len(hechos) > 1 else
                                                           f"Boleto {chr(65 + i)}" if len(hechos) > 1 else None))
                  for i, (b, av, fil) in enumerate(hechos)]
        pie = (f"¿Los guardo? /si guarda los {len(hechos)} · /no descarta todo" if len(hechos) > 1 else
               "¿Lo guardo? /si para guardar · /no para descartar")
        return "\n\n".join(partes) + "\n\n" + pie + " (si leí mal, mándalo otra vez más claro)"

    def texto_pendiente(self, b, avisos, fil, rotulo=None):
        cab = (f"{rotulo}: " if rotulo else f"Leí «{b['nombre']}»: " if b.get("nombre") else "Leí este boleto: ") + \
            f"{b['tipo'].lower()} de {len(b['patas'])} patas, {dinero(b.get('monto'))} → paga {pago_txt(b)}"
        out = [cab + (f" (n.º {b['numero']})" if b.get("numero") else "") + ":"]
        for f in fil:
            p = f["p"]
            lin = f"{p['k']}. {nombre_pata(p)}" + (f" · {p['partido']} {hora_ccs(p['inicio'])}" if p.get("partido") else " · ⚠️ sin juego")
            if f["pg"] is not None:
                lin += f" · P ≈ {pct(f['pg'] + f['pp'])}"
            out.append(lin)
        pr = b["previo"]
        out.append(f"P(cobrar) ≈ {pct(pr['p_cobrar'], 2)} {('(' + uno_de_cada(pr['p_cobrar']) + ')') if uno_de_cada(pr['p_cobrar']) else ''}".rstrip())
        if pr.get("ev") is not None:
            out.append(f"EV con la línea de ahora {pct(pr['ev'], 1)} · {costo_txt(pr['costo'])}")
        out.append("El EV contra el cierre aparece en /parlay cuando empiecen los juegos.")
        if pr.get("fuentes"):
            out.append("Líneas: " + ", ".join(pr["fuentes"]))
        out += ["⚠️ " + a for a in avisos]
        return "\n".join(out)

    def confirmar(self):
        pen = _leer_json(PENDIENTE, None)
        if not pen:
            return "No hay ningún boleto esperando confirmación. Mándame el boleto (foto, PDF o texto)."
        if pen.get("crudo"):          # leído por Gemini pero sin cruzar (ESPN no respondió): se cruza ahora y se vuelve a preguntar
            return self.preparar(pen["crudo"], archivo=pen.get("archivo"), nombre=pen.get("nombre"))
        boletos = pen.get("boletos") or ([pen["boleto"]] if pen.get("boleto") else [])
        hechos = []
        with candado():
            lista = self.todos()
            for b in boletos:
                b.setdefault("fase", 2)
                if not b.get("semana"):           # sin semana de ESPN (raro): la de ahora
                    b["temporada"], b["fase"], b["semana"] = self.semana_actual()
                clave = clave_semana(b)
                dela = self.de_semana(clave, lista)
                b.update(id=1 + max([x["id"] for x in lista], default=0), n=1 + max([x.get("n") or 0 for x in dela], default=0),
                         cargado=S.iso(self.ahora), estado="vivo", version=VERSION)
                propio = limpiar_nombre(b.get("nombre"))
                base = propio or f"{b['tipo'].capitalize()} {b['n']}"
                b["nombre_auto"] = not propio
                usados = {_clave_nombre(nombre_de(x)) for x in dela}
                nom, k = base, 2
                while _clave_nombre(nom) in usados or nom.isdigit():
                    nom, k = f"{base} ({k})", k + 1
                b["nombre"] = nom
                lista.append(b)
                hechos.append(b)
            self._guardar(lista)
            PENDIENTE.unlink()
        sem = nombre_semana(clave_semana(hechos[0])).lower()
        if len(hechos) == 1:
            b = hechos[0]
            pide = f"/parlay {b['n']}" if b["nombre_auto"] else f"/parlay {b['nombre']} o /parlay {b['n']}"
            return f"Guardado como «{b['nombre']}» ({sem}, n.º {b['n']}). Pide {pide} cuando quieras ver cómo va."
        b = hechos[0]
        pide = (f"Pide /parlay y el número para ver cada uno (por ejemplo, /parlay {b['n']})." if b["nombre_auto"] else
                f"Pide /parlay {b['nombre']} (o su número) para ver cada uno.")
        return f"Guardados ({sem}): " + " · ".join(f"«{x['nombre']}» (n.º {x['n']})" for x in hechos) + ". " + pide

    def descartar(self):
        if PENDIENTE.exists():
            PENDIENTE.unlink()
            return "Descartado. No guardé nada."
        return "No había nada por confirmar."

    def buscar(self, ref, lista=None):
        """ref (v1.3.1): número de esta semana («2»), semana y número («4.2»), o nombre (sin importar mayúsculas ni
        acentos; primero en esta semana, después en las anteriores). Devuelve (boleto, None) o (None, mensaje).
        Un nombre incompleto sirve si apunta a uno solo («domingo» → «Domingo 1» si no hay otro)."""
        lista = [b for b in (lista if lista is not None else self.todos()) if b.get("estado") != "borrado"]
        ref = str(ref or "").strip()
        actual = self.semana_actual()
        m = re.fullmatch(r"(\d{1,2})\s*[.\-/]\s*(\d{1,3})", ref)
        if ref.isdigit() or m:
            clave = (S.TEMPORADA, 2, int(m.group(1))) if m else actual
            n = int(m.group(2)) if m else int(ref)
            b = next((x for x in self.de_semana(clave, lista) if x.get("n") == n), None)
            if b:
                return b, None
            otras = sorted({clave_semana(x) for x in lista if x.get("n") == n and clave_semana(x) != clave}, reverse=True)
            pista = (f" ¿Era de la {nombre_semana(otras[0]).lower()}? /parlay {otras[0][2]}.{n}" if otras and otras[0][1] == 2 else "")
            return None, f"En la {nombre_semana(clave).lower()} no tienes el parlay {n}.{pista} /parlays muestra los de esta semana y /historico los anteriores."
        k = _clave_nombre(ref)
        if not k:
            return None, "Dime cuál: el número o el nombre."
        for grupo in (self.de_semana(actual, lista), sorted(lista, key=lambda x: (clave_semana(x), x["id"]))):
            exactos = [x for x in grupo if _clave_nombre(nombre_de(x)) == k]
            if exactos:
                return exactos[-1], None
            cand = [x for x in grupo if _clave_nombre(nombre_de(x)).startswith(k)]
            if len(cand) == 1:
                return cand[0], None
            if cand:
                return None, "Hay varios: " + " · ".join(f"/parlay {self.ref_corta(x, actual)}" for x in cand[-6:])
        return None, f"No encuentro «{ref}». /parlays muestra los de esta semana y /historico los anteriores."

    def ref_corta(self, b, actual=None):
        """Cómo pedir este boleto: el nombre si es de esta semana; si no, «semana.número»."""
        actual = actual or self.semana_actual()
        if clave_semana(b) == actual:
            return str(b.get("n")) if b.get("nombre_auto") else nombre_de(b)
        t, f, s = clave_semana(b)
        return f"{s}.{b.get('n')}" if f == 2 and t == S.TEMPORADA else nombre_de(b)

    def borrar(self, ref):
        with candado():
            lista = self.todos()
            b, msg = self.buscar(ref, lista)
            if b is None:
                return msg.replace("/parlay ", "/borrar_parlay ")
            b.update(estado="borrado", borrado=S.iso(self.ahora))
            self._guardar(lista)
        return (f"«{nombre_de(b)}» ({nombre_semana(clave_semana(b)).lower()}, n.º {b.get('n')}) borrado de la lista "
                "(queda en el registro marcado como borrado).")

    # -- resultados (v1.3.1): cada pata ya jugada guarda su resultado; el boleto se cierra cuando se decide
    def resultado_pata(self, f, fc_f):
        """Campos que guarda una pata cuyo juego terminó: resultado (G, P o E), marcador, línea de cierre (Pinnacle sin vig
        si el bot la tiene; si no, el consenso de nflverse), puntos contra el cierre y probabilidad de ganar al cierre."""
        p, j = f["p"], f["j"]
        loc, vis = j["local"], j["visita"]
        pl_, pv = int(loc.get("puntos") or 0), int(vis.get("puntos") or 0)
        out = dict(res="E" if f["pp"] == 1.0 else "G" if f["pg"] == 1.0 else "P",
                   marcador=f"{vis.get('apodo') or vis.get('abbr')} {pv} - {pl_} {loc.get('apodo') or loc.get('abbr')}",
                   p_cierre=None if fc_f is None or fc_f.get("pg") is None else round(fc_f["pg"], 4), final=S.iso(self.ahora))
        if j.get("cancelado"):
            out["res"] = "E"
        fila = self.fila_nfl(j)
        if fila:
            out["gid"] = fila["game_id"]
        if p.get("tipo") == "PROP":                     # v1.4 (42n)
            v, nom = valor_prop(p, f.get("res_final")) if f.get("res_final") is not None else (p.get("_valor"), None)
            out.update(valor=p.get("_valor") if v is None else v, jugador_espn=nom)
            return out
        r = self.ref(j, cierre=True)
        if p["tipo"] in ("ML", "SPREAD"):
            es_loc = p["equipo"] == loc.get("abbr")
            out.update(puntos_eq=pl_ if es_loc else pv, puntos_ri=pv if es_loc else pl_)
            out["margen"] = out["puntos_eq"] - out["puntos_ri"]
            if r is not None and r.ok():
                h = float(r.r["hcp_local"])
                out["cierre_linea"] = round(h if es_loc else -h, 2)
                out["cierre_fuente"] = r.fuente
                out["contra_cierre"] = round(out["margen"] + out["cierre_linea"], 2)
        else:
            out["total"] = pl_ + pv
            if r is not None and r.total is not None:
                out["cierre_linea"] = float(r.total)
                out["cierre_fuente"] = "consenso nflverse"
                d = out["total"] - r.total
                out["contra_cierre"] = round(d if p.get("lado_total", "OVER") == "OVER" else -d, 2)
        return out

    def actualizar(self):
        """Lee ESPN fuera del candado y escribe adentro: (1) cada pata cuyo juego terminó guarda resultado_pata; (2) el boleto
        vivo se cierra (perdido o cobrado) cuando se decide, como en v1.3. Devuelve cuántos boletos cambiaron."""
        cambios = {}
        for b in self.todos():
            if b.get("estado") == "borrado":
                continue
            falta = [p for p in b["patas"] if p.get("res") is None]
            if b.get("estado") != "vivo" and not falta:
                continue
            juegos = self.juegos_de(b)
            fa = self.filas(b, juegos, modo="ahora")
            fc = None
            cb, cp = {}, {}
            for i, f in enumerate(fa):
                if f["p"].get("res") is None and f["j"] is not None and f["j"]["estado"] == "post" \
                        and not (f["p"].get("tipo") == "PROP" and f["pg"] is None):      # v1.4: prop sin datos de ESPN: espera
                    fc = fc or self.filas(b, juegos, modo="cierre")
                    cp[f["p"]["k"]] = self.resultado_pata(f, fc[i])
            if b.get("estado") == "vivo" and not any(f["j"] is None for f in fa):
                perdida = any(f["j"]["estado"] == "post" and f["pg"] == 0.0 and f["pp"] == 0.0 for f in fa)
                if perdida or all(f["j"]["estado"] == "post" and not (f["p"].get("tipo") == "PROP" and f["pg"] is None) for f in fa):
                    fc = fc or self.filas(b, juegos, modo="cierre")
                    probs_c = [(f["pg"], f["pp"]) for f in fc]
                    ev_c = ev_boleto(b, probs_c)
                    decididas = [f for f in fa if f["j"]["estado"] == "post"]
                    cb = dict(estado="perdido" if perdida else "cobrado", cerrado=S.iso(self.ahora),
                              resultado=("perdido" if perdida else "cobró") + f" · acertó {sum(1 for f in decididas if f['pg'] == 1.0)} de {len(decididas)} patas ya jugadas",
                              cierre=dict(p_cobrar=p_cobrar(probs_c), ev=ev_c, costo=None if ev_c is None or not b.get("monto") else -ev_c * b["monto"],
                                          aciertos=sum(1 for f in decididas if f["pg"] == 1.0), decididas=len(decididas),
                                          esperados=round(sum(fc[i]["pg"] or 0 for i, f in enumerate(fa) if f["j"]["estado"] == "post"), 2)))
            if cb or cp:
                cambios[b["id"]] = (cb, cp)
        if cambios:
            with candado():
                lista = self.todos()
                for b in lista:
                    cb, cp = cambios.get(b["id"], ({}, {}))
                    if cb and b.get("estado") == "vivo":
                        b.update(cb)
                    for p in b["patas"]:
                        if p.get("k") in cp and p.get("res") is None:
                            p.update(cp[p["k"]])
                self._guardar(lista)
        return len(cambios)

    cerrar_resultados = actualizar        # nombre de v1-v1.3

    # -- textos para Telegram
    def _actualizar_callado(self):
        try:
            self.actualizar()
        except Exception as e:  # noqa: BLE001 — al log del servicio (stderr), no al mensaje
            print(f"parlay: no pude actualizar resultados ({type(e).__name__}: {str(e)[:120]})", file=sys.stderr)

    def texto_estado(self, ref=None):
        self._actualizar_callado()
        lista = [b for b in self.todos() if b.get("estado") != "borrado"]
        if not lista:
            return "No hay parlays guardados. Mándame el boleto de BetOnline (foto, PDF o texto)."
        if ref is None or not str(ref).strip():
            b = max(lista, key=lambda x: x["id"])
        else:
            b, msg = self.buscar(ref, lista)
            if b is None:
                return msg
        juegos = self.juegos_de(b)
        fa = self.filas(b, juegos, modo="ahora", con_resumen=True)
        fc = self.filas(b, juegos, modo="cierre")
        pc = p_cobrar([(f["pg"], f["pp"]) for f in fa])
        ev_c = ev_boleto(b, [(f["pg"], f["pp"]) for f in fc])
        costo_c = None if ev_c is None or not b.get("monto") else -ev_c * b["monto"]
        post = [f for f in fa if f["j"] and f["j"]["estado"] == "post"]
        gan = sum(1 for f in post if f["pg"] == 1.0)
        push = sum(1 for f in post if f["pp"] == 1.0)
        per = sum(1 for f in post if f["pg"] == 0.0 and (f["pp"] or 0.0) == 0.0)      # v1.4: un prop sin datos no cuenta como perdida
        vivas = len(fa) - gan - push - per
        estado = "PERDIDO" if per else ("COBRADO" if vivas == 0 else "vivo")
        out = [f"🎟 {nombre_de(b)} ({nombre_semana(clave_semana(b)).lower()}, n.º {b.get('n')}) · {b.get('tipo', 'parlay').lower()} de "
               f"{len(b['patas'])} patas · {dinero(b.get('monto'))} → paga {pago_txt(b)}"
               + (f" · boleto {b['numero']}" if b.get("numero") else ""),
               f"{estado}: {gan} ganadas · {per} perdidas · {push} push · {vivas} por decidir"]
        if estado == "vivo":
            out.append(f"P(cobrar) ahora ≈ {pct(pc, 1)}" + (f" ({uno_de_cada(pc)})" if uno_de_cada(pc) else "") + f" · al cargar {pct(b.get('previo', {}).get('p_cobrar'), 1)}")
        faltan_cierre = any(f["j"] and f["j"]["estado"] == "pre" for f in fa)
        out.append(f"EV contra el cierre {pct(ev_c, 1)} · {costo_txt(costo_c)}" + (" (los que no empezaron, con la línea de ahora)" if faltan_cierre else ""))
        out.append("")
        visto = set()
        for f in fa:
            p, j = f["p"], f["j"]
            if j is None:
                out.append(f"{p['k']} ⚠️ {nombre_pata(p)} · juego no encontrado")
                continue
            lin = f"{p['k']} {icono(j, f['pg'], f['pp'], p)} {nombre_pata(p)} · {marcador_txt(j)} · {avance_txt(p, j)}"
            if j["estado"] == "in" and not j.get("cancelado") and f["pg"] is not None and p.get("tipo") != "PROP":
                lin += " · " + prob_txt(p, f["pg"] + (f["pp"] or 0), estado_marcador(p, j))
            elif j["estado"] == "pre" and f["pg"] is not None and p.get("tipo") != "PROP":
                lin += f" · P ≈ {pct(f['pg'] + (f['pp'] or 0))}"
            out.append(lin)
            if j["estado"] == "post" and f["pg"] == 0.0 and f["pp"] == 0.0 and not j.get("cancelado"):
                out.append("   por qué: " + texto_por_que(p))
            if j["estado"] == "in" and j["id"] not in visto:
                visto.add(j["id"])
                ev = estado_vivo(j, f["res"])
                s, u = situacion_txt(j, ev), (ev.get("ultima") or "").strip()
                if s or u:
                    out.append("   " + " · ".join(x for x in (s, ("última: " + u[:100]) if u else "") if x))
        out += ["", "En vivo, el color sigue al marcador: 🟢 va ganando (o cubriendo; en totales, a ese ritmo) · 🔴 va perdiendo · "
                "⚪ empatado. «N de cada 100»: aproximación en juego (registro 42), no validada. Antes del juego: Pinnacle sin vig "
                "o consenso. Por qué falló: jugada por jugada de nflverse, sin IA. Por diversión: el motor no apuesta (31A)."]
        return "\n".join(out)

    def texto_lista(self):
        """v1.3.1 (42j): solo la semana NFL de ahora; las anteriores, en /historico."""
        self._actualizar_callado()
        todos = [b for b in self.todos() if b.get("estado") != "borrado"]
        actual = self.semana_actual()
        lista = self.de_semana(actual, todos)
        anteriores = sorted({clave_semana(b) for b in todos if clave_semana(b) != actual}, reverse=True)
        pie = (f"Semanas anteriores: /historico (por ejemplo, /historico {nombre_semana(anteriores[0], corto=True).lower()})"
               if anteriores else "")
        if not lista:
            return "\n".join([f"{nombre_semana(actual)}: todavía no cargaste parlays. Escribe /parlay para cargar uno."] + ([pie] if pie else []))
        out = [f"Tus parlays de la {nombre_semana(actual).lower()} ({fechas_txt(p.get('inicio') for b in lista for p in b['patas'])}):"]
        for b in lista:
            pr = b.get("previo", {})
            if b.get("estado") in ("cobrado", "perdido"):           # v1.3.2: aciertos desde las patas
                fin = ("cobró" if b["estado"] == "cobrado" else "perdido") + " · " + aciertos_txt(b)
            else:
                fin = b.get("resultado") or f"en juego · /parlay {self.ref_corta(b, actual)}"
            out.append(f"{b.get('n')} · «{nombre_de(b)}» · {hora_ccs(b.get('cargado'))} · {len(b['patas'])} patas · {dinero(b.get('monto'))} → "
                       f"{pago_txt(b)} · P(cobrar) al cargar {pct(pr.get('p_cobrar'), 1)} · {fin}")
        r = resumen_semana(lista)
        if r["decididas"]:
            out += ["", f"Patas ya jugadas: acertaste {r['aciertos']} de {r['decididas']}; según el cierre se esperaban {fi(round(r['esperados'], 1))}."]
        if pie:
            out += ["", pie]
        return "\n".join(out)

    def texto_historico(self, arg=None):
        """v1.3.1 (42j): sin semana, la lista de semanas por fecha (la más nueva primero); con semana, cada parlay con el
        resultado de cada pata y, en las perdidas, por qué falló."""
        self._actualizar_callado()
        todos = [b for b in self.todos() if b.get("estado") != "borrado"]
        if not todos:
            return "No hay parlays guardados todavía."
        actual = self.semana_actual()
        semanas = sorted({clave_semana(b) for b in todos}, reverse=True)
        enlace = f"La hoja con todas las semanas: https://docs.google.com/spreadsheets/d/{hoja_parlays_id()}"
        if not arg or not str(arg).strip():
            out = ["Tus semanas (la más nueva primero):"]
            for c in semanas:
                bs = self.de_semana(c, todos)
                r = resumen_semana(bs)
                cob = sum(1 for b in bs if b.get("estado") == "cobrado")
                per = sum(1 for b in bs if b.get("estado") == "perdido")
                viv = len(bs) - cob - per
                partes = [f"{len(bs)} parlay{'s' if len(bs) != 1 else ''}: {cob} cobrado{'s' if cob != 1 else ''}, {per} perdido{'s' if per != 1 else ''}"
                          + (f", {viv} en juego" if viv else "")]
                if r["decididas"]:
                    partes.append(f"patas {r['aciertos']} de {r['decididas']} (se esperaban {fi(round(r['esperados'], 1))})")
                out.append(f"• {nombre_semana(c)} ({fechas_txt(p.get('inicio') for b in bs for p in b['patas'])})"
                           + (" · esta semana" if c == actual else "") + " · " + " · ".join(partes)
                           + f" → /historico {nombre_semana(c, corto=True).lower()}")
            return "\n".join(out + ["", enlace])
        clave = leer_semana(arg)
        if clave is None or clave not in semanas:
            return (f"No tengo parlays de «{str(arg).strip()[:20]}». Semanas con parlays: "
                    + ", ".join(nombre_semana(c, corto=True) for c in semanas) + ". Por ejemplo: /historico " + nombre_semana(semanas[0], corto=True).lower())
        bs = self.de_semana(clave, todos)
        r = resumen_semana(bs)
        out = [f"{nombre_semana(clave)} ({fechas_txt(p.get('inicio') for b in bs for p in b['patas'])})"
               + (f" · patas: acertaste {r['aciertos']} de {r['decididas']} (se esperaban {fi(round(r['esperados'], 1))})" if r["decididas"] else "")]
        if r["causas"]:
            out.append("Por qué fallaron: " + causas_txt(r["causas"]))
        for b in bs:
            ci = b.get("cierre") or {}
            est = {"cobrado": "✅ COBRADO", "perdido": "❌ PERDIDO"}.get(b.get("estado"), "⏳ en juego")
            out += ["", f"{b.get('n')} · «{nombre_de(b)}» · {b.get('tipo', 'parlay').lower()} de {len(b['patas'])} patas · "
                        f"{dinero(b.get('monto'))} → {pago_txt(b)} · {est}"]
            if ci:
                out.append(f"   P(cobrar) al cierre {pct(ci.get('p_cobrar'), 2)} · EV contra el cierre {pct(ci.get('ev'), 1)} · {costo_txt(ci.get('costo'))}")
            for p in b["patas"]:
                ic = {"G": "✅", "P": "❌", "E": "🟡"}.get(p.get("res"), "⏳")
                lin = f"   {ic} {pata_corta(p)}" + (f" · {p['marcador']}" if p.get("marcador") else (f" · {p.get('partido')}" if p.get("partido") else ""))
                out.append(lin)
                if p.get("res") == "P":
                    out.append("      por qué: " + texto_por_que(p))
        return "\n".join(out + ["", enlace])

    def texto_jugadas(self, equipo, n=10):
        eq = _abbr((equipo or "").upper().strip())
        if not eq:
            return "Dime el equipo: /jugadas BUF"
        j = next((x for x in juegos_del_tablero(self.espn.tablero()) if eq in (x["local"].get("abbr"), x["visita"].get("abbr"))), None)
        if not j:
            return f"No veo a {eq} en el calendario de esta semana."
        if j["estado"] == "pre":
            return f"{marcador_txt(j)}: empieza el {hora_ccs(j['inicio'])} (Caracas)."
        res = self.espn.resumen(j["id"])
        out = [marcador_txt(j)]
        s = situacion_txt(j, estado_vivo(j, res))
        if s:
            out.append(s)
        out.append(f"Últimas {n} jugadas (la más nueva arriba):")
        for p in jugadas_de_resumen(res, n):
            cu = {1: "1.º", 2: "2.º", 3: "3.º", 4: "4.º"}.get(p["periodo"], "TE")
            dd = f"{p['down']}.º y {p['dist']} · " if p.get("down") in (1, 2, 3, 4) else ""
            out.append(f"{cu} {p['reloj']} · {p['ataque']} · {dd}{'🏈 ' if p['anota'] else ''}{p['texto'][:120]} "
                       f"({j['visita']['abbr']} {p['visita']}-{p['local']} {j['local']['abbr']})")
        return "\n".join(out)


# ---------------------------------------------------------------- v1.3.1 (42k): por qué falló cada pata, sin IA
COLS_RAZONES = ["game_id", "play_id", "posteam", "defteam", "play_type", "yards_gained", "interception", "fumble_lost",
                "touchdown", "td_team", "return_touchdown", "qb_dropback", "passer_player_name", "rusher_player_name", "desc",
                "wind", "weather", "roof"]


def _norm_jug(x):
    return re.sub(r"[^a-z]", "", re.sub(r"\b(jr|sr|ii|iii|iv)\b\.?", "", (x or "").lower()))


def _qb_txt(x):
    return str(x or "?").replace(".", ". ").replace("  ", " ")


def _edad_dias(iso, ahora):
    t = S.t_utc(iso)
    return 0.0 if t is None else (ahora - t).total_seconds() / 86400


class Razones:
    """Hechos de un partido en la jugada por jugada de nflverse y los snaps (PFR vía nflverse). Las mismas reglas con las
    que Claude llenó la hoja de la semana 4 (registro 42, 42k), con una corrección: los balones perdidos en jugadas de
    patada de despeje no se le cuentan al equipo que pateó (nflverse lo pone como posteam)."""

    def __init__(self, pbp=None, snaps=None):
        self.pbp, self.snaps, self._p = pbp, snaps, {}

    def cargar(self, max_edad_h=EDAD_PBP_H):
        import polars as pl
        DATOS_P.mkdir(parents=True, exist_ok=True)
        rp, rs = DATOS_P / f"pbp_{S.TEMPORADA}.parquet", DATOS_P / f"snap_counts_{S.TEMPORADA}.csv"
        if S.bajar(S.URL_PBP.format(S.TEMPORADA), rp, 100_000, max_edad_h):
            cols = [c for c in COLS_RAZONES if c in pl.read_parquet_schema(rp)]
            self.pbp = pl.read_parquet(rp, columns=cols)
        if S.bajar(URL_SNAPS.format(S.TEMPORADA), rs, 10_000, max_edad_h):
            self.snaps = pl.read_csv(rs, infer_schema_length=0)
        self._p = {}
        return self

    def juego(self, gid):
        import polars as pl
        if gid not in self._p:
            self._p[gid] = None if self.pbp is None else self.pbp.filter(pl.col("game_id") == gid)
        p = self._p[gid]
        return p if p is not None and p.height >= 50 else None      # menos de 50 jugadas: todavía incompleto

    def con_snaps(self, gid):
        import polars as pl
        return self.snaps is not None and self.snaps.filter(pl.col("game_id") == gid).height > 0

    def hechos(self, gid, eq, rival):
        """Balones perdidos, TD de defensa o especiales, yardas por jugada, QB que no terminó y titulares lesionados."""
        import polars as pl
        p = self.juego(gid)
        tov = p.filter(pl.col("play_type").fill_null("") != "punt")
        to = {t: int(tov.filter(pl.col("posteam") == t).select((pl.col("interception").fill_null(0) + pl.col("fumble_lost").fill_null(0)).sum()).item() or 0)
              for t in (eq, rival)}
        td = p.filter((pl.col("touchdown") == 1) & pl.col("td_team").is_not_null() &
                      ((pl.col("td_team") != pl.col("posteam")) | (pl.col("return_touchdown") == 1)))
        tdd = {t: td.filter(pl.col("td_team") == t).height for t in (eq, rival)}
        jug = p.filter(pl.col("play_type").is_in(["pass", "run"]) & pl.col("yards_gained").is_not_null())
        ypp = {t: (jug.filter(pl.col("posteam") == t)["yards_gained"].mean() or 0.0) for t in (eq, rival)}
        db = p.filter((pl.col("qb_dropback") == 1) & (pl.col("posteam") == eq)).sort("play_id")
        qbs = db.with_columns(pl.coalesce(["passer_player_name", "rusher_player_name"]).alias("qb"))["qb"].drop_nulls().to_list()
        qb_salio = None
        if qbs:
            cnt = {q: qbs.count(q) for q in set(qbs)}
            otros = {q: c for q, c in cnt.items() if q != qbs[0] and c >= 5}
            if otros:
                qb_salio = (qbs[0], max(otros, key=otros.get))
        lesionados = []
        if self.con_snaps(gid):
            abrevs = set()
            for d in p["desc"].drop_nulls().to_list():
                for t, ab in re.findall(r"\b([A-Z]{2,3})-\d+-([A-Za-z][A-Za-z'.\- ]*?) was injured", d):
                    if t == eq:
                        abrevs.add(ab.strip())
            s = self.snaps.filter(pl.col("team") == eq)
            for nom in s["player"].unique().to_list():
                part = {r["game_id"]: max(float(r["offense_pct"] or 0), float(r["defense_pct"] or 0))
                        for r in s.filter(pl.col("player") == nom).to_dicts()}
                antes = [v for k, v in part.items() if k < gid]
                if gid not in part or part[gid] >= 0.5 or not antes or sum(antes) / len(antes) < 0.5:
                    continue
                pr = str(nom).split()
                if len(pr) < 2:
                    continue
                for ab in abrevs:
                    if "." in ab:
                        pre, ape = ab.split(".", 1)
                        if _norm_jug(ape) == _norm_jug(" ".join(pr[1:])) and _norm_jug(pr[0]).startswith(_norm_jug(pre)):
                            lesionados.append(nom)
                            break
        return dict(to=to, tdd=tdd, ypp=ypp, qb=qb_salio, les=sorted(lesionados))

    def clima(self, gid):
        p = self.juego(gid)
        fila = p.head(1).to_dicts()[0] if p is not None and p.height else {}
        techo = str(fila.get("roof") or "").lower()
        if techo in ("dome", "closed"):
            return None, False
        w = fila.get("wind")
        txt = str(fila.get("weather") or "").lower()
        return (int(w) if w is not None else None), any(x in txt for x in ("rain", "snow", "shower", "sleet"))

    def explicar(self, gid, p, local, visita, ahora=None):
        """Texto y causas de una pata perdida; None si nflverse todavía no publicó el partido."""
        if p.get("tipo") == "PROP":                     # v1.4 (42n): con lo que guardó ESPN, sin esperar a nflverse
            st = PROP_STATS.get(p.get("stat"), ((), "", ""))
            v = p.get("valor")
            linea = float(p.get("linea") if p.get("linea") is not None else 0.5)
            txt = (f"Terminó con {num_txt(v)} {st[1] if v is not None and abs(v - 1) < 1e-9 else st[2]}; "
                   f"necesitaba {umbral_txt(p)}.") if v is not None else "Sin datos de ESPN."
            return dict(texto=txt, causas=["prop"], parcial=False, version=RAZONES_VERSION, hora=S.iso(ahora or ahora_utc()))
        if self.juego(gid) is None:
            return None
        ahora = ahora or ahora_utc()
        partes, causas = [], []
        contra = p.get("contra_cierre")
        if p["tipo"] in ("ML", "SPREAD"):
            eq = p["equipo"]
            rival = visita if eq == local else local
            h = self.hechos(gid, eq, rival)
            pe, pr = int(p.get("puntos_eq") or 0), int(p.get("puntos_ri") or 0)
            m = pe - pr
            if p["tipo"] == "ML":
                partes.append(f"{'Perdió' if m < 0 else 'Empató'} {pe}-{pr}.")
            else:
                partes.append(f"{'Perdió' if m < 0 else 'Ganó' if m > 0 else 'Empató'} {pe}-{pr} y no cubrió el {linea_eq_txt(p.get('linea'))}.")
            if h["to"][eq] - h["to"][rival] >= 2:
                partes.append(f"Perdió más balones ({h['to'][eq]} contra {h['to'][rival]}).")
                causas.append("balones")
            if h["tdd"][rival]:
                partes.append(f"Los {APODO_EQ.get(rival, rival)} anotaron {h['tdd'][rival]} TD de defensa o de equipos especiales.")
                causas.append("td_def")
            if h["qb"]:
                partes.append(f"Su QB titular ({_qb_txt(h['qb'][0])}) no terminó el partido; entró {_qb_txt(h['qb'][1])}.")
                causas.append("qb")
            if h["les"]:
                partes.append("Se lesionaron titulares durante el partido: " + ", ".join(h["les"][:3]) + ".")
                causas.append("lesion")
            if h["ypp"][rival] - h["ypp"][eq] >= 1.0:
                partes.append(f"Los {APODO_EQ.get(rival, rival)} movieron mejor el balón: {fi(round(h['ypp'][rival], 1))} yardas por jugada "
                              f"contra {fi(round(h['ypp'][eq], 1))}.")
                causas.append("rival_mejor")
            if not causas:
                if m < 0:
                    partes.append("Sin una causa clara en los datos: " + (f"partido parejo, se decidió por {-m}." if -m <= 8 else f"perdió por {-m}."))
                else:
                    nec = media_txt(abs(float(p.get("linea") or 0)))
                    partes.append(f"Sin una causa clara en los datos: {'ganó por ' + str(m) if m > 0 else 'empató'} y necesitaba ganar por más de {nec}.")
                causas.append("sin_causa")
            if contra is not None and contra <= -UMBRAL_SORPRESA:
                partes.append(f"Sorpresa grande: {num_txt(abs(contra))} puntos peor que la línea de cierre.")
                causas.append("sorpresa")
        else:
            over = p.get("lado_total", "OVER") == "OVER"
            tot, linea = int(p.get("total") or 0), float(p.get("linea") or 0)
            d = tot - linea
            partes.append(f"Se anotaron {tot} puntos; la línea era {media_txt(linea)} ({media_txt(abs(d))} {'menos' if d < 0 else 'más'}).")
            h1, h2 = self.hechos(gid, local, visita), self.hechos(gid, visita, local)
            to = h1["to"][local] + h1["to"][visita]
            if over:
                viento, lluvia = self.clima(gid)
                if viento is not None and viento >= 15:
                    partes.append(f"Hubo viento fuerte ({viento} mph).")
                    causas.append("clima")
                elif lluvia:
                    partes.append("Jugaron con lluvia o nieve.")
                    causas.append("clima")
                for eq, h in ((local, h1), (visita, h2)):
                    if h["qb"]:
                        partes.append(f"El QB titular de los {APODO_EQ.get(eq, eq)} ({_qb_txt(h['qb'][0])}) no terminó el partido; entró {_qb_txt(h['qb'][1])}.")
                        if "qb" not in causas:
                            causas.append("qb")
                if to >= 4:
                    partes.append(f"Hubo {to} balones perdidos entre los dos.")
                    causas.append("balones")
            else:
                n_td = h1["tdd"][local] + h1["tdd"][visita]
                if n_td:
                    partes.append(f"Hubo {n_td} TD de defensa o de equipos especiales.")
                    causas.append("td_def")
                if to >= 4:
                    partes.append(f"Hubo {to} balones perdidos entre los dos (campos cortos).")
                    causas.append("balones")
            if not causas:
                partes.append("Sin una causa clara en los datos.")
                causas.append("sin_causa")
            if contra is not None and contra <= -UMBRAL_SORPRESA:
                partes.append(f"Sorpresa grande: {num_txt(abs(contra))} puntos {'menos' if over else 'más'} que el total de cierre.")
                causas.append("sorpresa")
        return dict(texto=" ".join(partes), causas=causas, parcial=not self.con_snaps(gid), version=RAZONES_VERSION, hora=S.iso(ahora))


def explicar_pendientes(P, R=None):
    """Razón de cada pata perdida que todavía no la tiene (o la tiene incompleta, sin snaps). Baja nflverse solo si hace
    falta. Escribe adentro del candado. Devuelve cuántas razones nuevas guardó."""
    pend = []
    for b in P.todos():
        if b.get("estado") == "borrado":
            continue
        for p in b["patas"]:
            if p.get("res") != "P":
                continue
            pq = p.get("por_que") or {}
            if pq and pq.get("version") == RAZONES_VERSION and (not pq.get("parcial") or _edad_dias(p.get("final"), P.ahora) > ESPERA_PBP_DIAS):
                continue
            pend.append((b, p))
    if not pend:
        return 0
    R = R or Razones().cargar()
    nuevos = {}
    for b, p in pend:
        eqs = [x.strip() for x in str(p.get("partido") or "").split("@")]
        gid = p.get("gid") or (P.fila_de_pata(b, p) or {}).get("game_id")
        if not gid or len(eqs) != 2:
            continue
        x = R.explicar(gid, p, eqs[1], eqs[0], P.ahora)
        if x is None:
            if _edad_dias(p.get("final"), P.ahora) <= ESPERA_PBP_DIAS:
                continue
            x = dict(texto=f"nflverse no publicó la jugada por jugada de este partido en {ESPERA_PBP_DIAS} días.", causas=["sin_datos"],
                     parcial=False, version=RAZONES_VERSION, hora=S.iso(P.ahora))
        viejo = p.get("por_que") or {}
        if (viejo.get("texto"), viejo.get("causas"), viejo.get("parcial"), viejo.get("version")) == (x["texto"], x["causas"], x["parcial"], x["version"]):
            continue
        nuevos[(b["id"], p["k"])] = x
    if nuevos:
        with candado():
            lista = P.todos()
            for b in lista:
                for p in b["patas"]:
                    if (b["id"], p.get("k")) in nuevos:
                        p["por_que"] = nuevos[(b["id"], p["k"])]
            P._guardar(lista)
    return len(nuevos)


