def main(argv):
    if not argv:
        print(__doc__)
        return 0
    cmd, resto = argv[0], argv[1:]
    try:
        if cmd in ("leer", "foto") and resto:
            codigo, texto = leer_cli(resto)
            print(texto)
            return codigo
        elif cmd == "si":
            print(Parlays().confirmar())
        elif cmd == "no":
            print(Parlays().descartar())
        elif cmd == "lista":
            print(Parlays().texto_lista())
        elif cmd == "estado":
            print(Parlays().texto_estado(" ".join(resto) if resto else None))
        elif cmd == "jugadas":
            print(Parlays().texto_jugadas(resto[0] if resto else ""))
        elif cmd == "borrar" and resto:
            print(Parlays().borrar(" ".join(resto)))
        elif cmd == "historico":
            print(Parlays().texto_historico(" ".join(resto) if resto else None))
        elif cmd == "auto":
            print(f"[{ahora_utc():%Y-%m-%d %H:%M:%S} UTC] " + modo_auto(), flush=True)
        elif cmd == "hoja":
            P = Parlays()
            P._actualizar_callado()
            print(escribir_hoja(P, forzar=True))
        elif cmd == "prueba":
            print(prueba_instalacion())
        elif cmd == "diagnostico":
            print(diagnostico(resto[0] if resto else None))
        elif cmd == "claude-prueba":
            print(claude_prueba())
        else:
            print("Orden no reconocida. " + __doc__)
            return 2
    except Exception as e:  # noqa: BLE001 — mensaje corto para Telegram; el detalle va al log del servicio
        import traceback
        traceback.print_exc(file=sys.stderr)
        print(f"No pude completar la orden ({type(e).__name__}). Si se repite, revisa salidas/semana/orden.log.")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
